/* Minimal EmailJS shim using EmailJS REST API
   - Provides `emailjs.init(userId)` and `emailjs.sendForm(service_id, template_id, formElement)`
   - This is a small replacement for the CDN SDK so the page works offline.
   - It sends a POST to https://api.emailjs.com/api/v1.0/email/send
*/
(function(window){
  'use strict';
  var emailjs = {};
  emailjs._userId = null;

  emailjs.init = function(userId){
    emailjs._userId = userId;
  };

  function formToParams(form){
    var params = {};
    if(!form) return params;
    var el;
    for(var i=0;i<form.elements.length;i++){
      el = form.elements[i];
      if(!el.name) continue;
      if(el.type === 'checkbox') params[el.name] = el.checked;
      else if(el.type === 'radio') { if(el.checked) params[el.name] = el.value; }
      else params[el.name] = el.value;
    }
    return params;
  }

  emailjs.sendForm = function(service_id, template_id, form){
    return new Promise(function(resolve, reject){
      try{
        var template_params = formToParams(form);
        var payload = {
          service_id: service_id,
          template_id: template_id,
          user_id: emailjs._userId || '',
          template_params: template_params
        };

        fetch('https://api.emailjs.com/api/v1.0/email/send', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(payload)
        }).then(function(resp){
          if(resp.ok) return resp.json().catch(function(){ return {}; });
          return resp.text().then(function(text){ throw new Error(text || resp.statusText); });
        }).then(function(data){ resolve(data); })
        .catch(function(err){ reject(err); });
      } catch(e){ reject(e); }
    });
  };

  window.emailjs = window.emailjs || emailjs;
})(window);
